#### native.semantic-universe.typescript.v2 {"document": "native/native-evidence.schemas.v2.json", "selector": "#/$defs/TypeScriptUniverseV2ResolvedInputs", "contextField": ["nativeContextId"], "contextForm": "sha256-text", "language": "typescript", "binding": {"contract": "native-evidence", "section": "11", "entryPoint": "bind_typescript_universe", "arguments": ["universe", "admission", "context", "retained", "snapshotInventory"]}, "contextDomain": "native.context.typescript.v2", "nestedIdentities": [], "nestedRecords": [{"path": ["tsconfigGraphHash"], "retainedAs": "configGraph", "form": "canonical-record", "document": "native/native-evidence.schemas.v2.json", "selector": "#/$defs/TypeScriptConfigGraphV1"}], "languageVersionBinding": {"record": "#/$defs/body-language-version", "encoding": "raw-32-byte-sha256-of-canonical-record", "retention": "derived", "fields": {"compilerName": {"source": "native-context", "path": ["toolchain", "compilerName"]}, "compilerVersion": {"source": "native-context", "path": ["toolchain", "compilerVersion"]}, "compilerBuild": {"source": "native-context", "path": ["toolchain", "compilerPackageDigest"]}}, "dialect": {"key": "sourceVariant", "source": "anchor-path-suffix", "form": "closed-suffix-table", "table": {".d.ts": "ts-declaration", ".ts": "ts", ".tsx": "tsx", ".mts": "mts", ".cts": "cts", ".js": "js", ".jsx": "jsx", ".mjs": "mjs", ".cjs": "cjs"}, "onUnknown": "BODY_LANGUAGE_SOURCE_VARIANT_UNKNOWN", "selectionLaw": "TypeScript has no per-crate dialect map; its per-body axis is the SOURCE VARIANT its own file suffix denotes, which decides how the body is scanned and parsed. Longest matching suffix wins, so .d.ts is never read as .ts. An unlisted suffix REFUSES rather than being folded into a neighbouring variant, so a normal variant is never silently mis-assigned and a new one must be registered deliberately. Distinct suffixes stay distinct even where a parser would treat two alike: this can fail to equate two bodies that are in fact equivalent, and can never equate two the language reads differently. Collapsing variants is a claim about a parser and belongs to the level specification. Only the variant token enters the record; the path does not."}, "excluded": {"libSelection": "standard library selection resolves types; it does not interpret a body span", "typescriptStdlibMerkleRoot": "same, and it is a retained artifact digest not a language identity", "standardLibraryComponentDigests": "same", "languageMode": "configuration and program assembly, not the language", "synthesizerVersion": "the option synthesizer, not the compiler that reads the body", "packageModuleType": "module resolution semantics, not body interpretation", "anchorPath": "the path establishes the variant and then does not enter the record; two identical bodies at different paths in one variant have one identity"}, "bodyLanguages": ["typescript", "javascript"], "bodyLanguageByVariant": {"ts": "typescript", "tsx": "typescript", "ts-declaration": "typescript", "mts": "typescript", "cts": "typescript", "js": "javascript", "jsx": "javascript", "mjs": "javascript", "cjs": "javascript"}, "bodyLanguageLaw": "The body languageId is DERIVED from the selected source variant, not from the provider universe. The universe language is the engine that reads the body; a .js body read by the TypeScript engine is a javascript body and must carry that identifier, exactly as native section 6.3 requires. The frame languageId and the record languageId are both taken from this one selector over the same anchor, so they cannot disagree. No JavaScript body is rewritten as TypeScript, and the cross-tsjs candidate projection of section 6.4 is untouched.", "bodyEligibility": {"form": "dialect-table"}, "normalizationClosure": {"source": "native-context", "path": ["toolClosure", "closureId"], "kind": "toolchain"}}}
#### native.semantic-universe.rust.v2 {"document": "native/native-evidence.schemas.v2.json", "selector": "#/$defs/RustUniverseV2ResolvedInputs", "language": "rust", "contextDomain": "native.context.rust.v2", "contextField": ["nativeContextId"], "contextForm": "sha256-text", "contextAgreementFields": ["dependencySourceSetId", "unifiedFeaturesId", "preparedOutputSetId"], "snapshotJoins": [{"path": ["crateRootPaths"], "form": "inventoried-paths"}, {"path": ["lockfileIdentity"], "form": "inventoried-path-and-digest", "pathField": "path", "digestField": "contentSha256"}], "binding": {"contract": "native-evidence", "section": "2.1/11", "entryPoint": "bind_rust_universe", "arguments": ["universe", "admission", "context", "retained", "snapshotInventory"]}, "nestedIdentities": [{"path": ["dependencySourceSetId"], "form": "sha256-text", "domainSet": "native-nested", "retainedAs": "dependencySourceSet"}, {"path": ["unifiedFeaturesId"], "form": "sha256-text", "domainSet": "native-nested", "retainedAs": "unifiedFeatures"}, {"path": ["preparedOutputSetId"], "form": "sha256-text", "domainSet": "native-nested", "nullable": true, "retainedAs": "preparedOutputSet"}, {"path": ["configProjectionSha256"], "form": "bare-hex", "domainSet": "native-nested"}, {"path": ["sourceUnitOwnershipId"], "form": "sha256-text", "domainSet": "native-nested", "nullable": true, "retainedAs": "sourceUnitOwnership"}], "preparedResolutionGrantOperations": {"host-prepared": "prepare-code", "imported-inert": "read-import", "none": null}, "languageVersionBinding": {"record": "#/$defs/body-language-version", "encoding": "raw-32-byte-sha256-of-canonical-record", "retention": "derived", "fields": {"compilerName": {"const": "rustc"}, "compilerVersion": {"source": "native-context", "path": ["toolchain", "rustcVersion"]}, "compilerBuild": {"source": "native-context", "path": ["toolchain", "rustCommitHash"]}}, "dialect": {"key": "edition", "source": "universe", "path": ["edition"], "form": "selected-compilation-target-edition", "ownership": {"source": "retained", "retainedAs": "sourceUnitOwnership", "pathField": "path", "unitField": "unitId", "unitsField": "units", "crateField": "crateName", "targetEditionField": "targetEdition", "selectionField": "selectedUnitIds", "enumerationField": "enumeration"}, "onEmpty": "BODY_LANGUAGE_DIALECT_ABSENT", "onAmbiguous": "BODY_LANGUAGE_DIALECT_AMBIGUOUS", "onOwnerNotCompiled": "BODY_LANGUAGE_OWNER_NOT_COMPILED", "onOwnerUnenumerated": "BODY_LANGUAGE_OWNER_UNENUMERATED", "onOwnerAmbiguous": "BODY_LANGUAGE_OWNER_AMBIGUOUS", "onOwnershipMissing": "BODY_LANGUAGE_OWNERSHIP_REQUIRED", "selectionLaw": "The dialect is the EFFECTIVE edition of the SELECTED compilation target that owns this body path: the unit targetEdition when it states one, otherwise the universe edition map entry for its crateName. There is NO fast path - Cargo lets a target override its package default, so package defaults that all agree still do not determine a body dialect - and a clones fact over any Rust universe therefore requires the committed SourceUnitOwnershipV1 whatever the package map looks like. The order of decision is fixed and each step has its own cause: (1) no committed ownership refuses; (2) enumeration partial refuses BEFORE any row is looked at, so incomplete discovery can never act as an implicit edition selection by hiding a conflicting owner; (3) rows are those whose path EQUALS the enclosing fact anchor path - never a prefix, never a nearest directory, never a first match - and no row at all refuses as not-compiled; (4) rows are then restricted to selectedUnitIds, and a path compiled only by unselected targets refuses as not-selected rather than borrowing an out-of-scope edition; (5) SELECTED owners whose effective editions AGREE are admissible, which is the ordinary shared-file and lib-plus-test-target case; (6) selected owners that DISAGREE are an ambiguous unselected request and refuse. Because selectedUnitIds is committed inside the record whose H identity the universe names, each selection is a DIFFERENT sourceUniverse: one physical path compiled at two editions is validly analysed under each, one selection at a time. Selection establishes the JOIN only - no path, crate name, unit id or selection enters the body-language-version record.", "alwaysRequired": true, "onOwnerNotSelected": "BODY_LANGUAGE_OWNER_NOT_SELECTED", "scopeVersusEnumeration": "SELECTED SCOPE and INCOMPLETE ENUMERATION are different claims and neither substitutes for the other. A selection says these targets ARE the analysis, so an owner outside them is deliberately out of scope and its edition does not bear on this body; the selection is committed in the identity, so it is visible to every consumer and changes the universe. Incomplete enumeration says the producer did not finish, so an owner INSIDE the selected scope may exist that is not listed and could contradict a listed one; that is a gap in knowledge, it is not visible as a selection, and it therefore admits no body dialect at all. Silently om
#### native.semantic-universe.syntax.v2 {"document": "native/native-evidence.schemas.v2.json", "selector": "#/$defs/SyntaxUniverseV2ResolvedInputs", "contextField": ["nativeContextId"], "contextForm": "sha256-text", "language": "syntax", "binding": {"contract": "native-evidence", "section": "1.2", "entryPoint": "bind_syntax_universe", "arguments": ["universe", "admission", "context", "retained", "snapshotInventory"]}, "contextDomain": "native.context.syntax.v2", "nestedIdentities": [], "nestedRecords": [], "note": "The universe of the syntax-only mode. `semantic universe` names the thing that DETERMINES a fact, and for a grammar-only analysis that is the selected bundled-grammar set, not a compiler semantic model. It exists because the capability matrix advertises declares/literal/control-flow at `syntactic` and clones at `normalized-body-hash` for syntax-only, and because file/package/vcs-change inventory facts must be representable in a repository that contains no TypeScript and no Rust unit at all: fact2 and subject-scope both REQUIRE a universe h-identity from this closed domain set, so with only the two compiler universes registered those advertised cells could mint no fact and no scope. Making the universe fields nullable was rejected: it would delete the invariant that every fact states what produced it, and would leave `which grammar read this body` unanswerable for exactly the facts that depend on it. Semantic capability is NOT widened by this domain - a syntax-only universe can carry only the syntactic and inventory rungs and the clones rung; imports/references/calls/types/reachability remain language-tier-unsupported, and a universal negative still requires its own complete Coverage.", "languageVersionBinding": {"record": "#/$defs/body-language-version", "encoding": "raw-32-byte-sha256-of-canonical-record", "retention": "derived", "fields": {"compilerName": {"source": "native-context", "path": ["grammarBundle", "parserName"]}, "compilerVersion": {"source": "native-context", "path": ["grammarBundle", "parserVersion"]}, "compilerBuild": {"source": "native-context", "path": ["grammarBundle", "bundleDigest"]}}, "componentLaw": "body-language-version names THE COMPONENT THAT INTERPRETS THE BODY SPAN - explicitly not the build tool and not the resolver. Under syntax-only that component is the bundled grammar's parser, so the three fields are bound to the retained, closure-joined grammar bundle rather than to a toolchain. No static constant and no fabricated compiler identity is used: parserVersion is joined by admission to the grammar closure's manifest semanticVersion exactly as the compiler versions are, and bundleDigest is the exact retained bundle identity. A body read by the grammar therefore has a DIFFERENT languageVersion from the same bytes read by tsc or rustc, so their clone identities differ. That is required, not incidental: equating a grammar parse with a compiler parse would assert an interpretation that was never performed.", "dialect": {"key": "grammarVariant", "source": "anchor-path-suffix", "form": "closed-suffix-table", "table": {".rs": "rs", ".d.ts": "ts-declaration", ".ts": "ts", ".tsx": "tsx", ".mts": "mts", ".cts": "cts", ".js": "js", ".jsx": "jsx", ".mjs": "mjs", ".cjs": "cjs"}, "onUnknown": "BODY_LANGUAGE_GRAMMAR_VARIANT_UNKNOWN", "selectionLaw": "A syntax-only analysis has no compilation unit, so it has no edition to select and no program to join; its only per-body axis is the variant the bundled grammar selects from the body's own suffix. Longest matching suffix wins, so .d.ts is never read as .ts. A suffix with no bundled grammar REFUSES rather than being folded into a neighbouring variant - which is the same conservative rule the compiler universes use, and it is what keeps `unsupported-file / no-bundled-grammar` an honest classification rather than a silent reinterpretation. Crucially there is NO edition branch here: a .rs body read without Cargo has no admitted ownership, and inventing one would be exactly the fabricated compiler semantics this mode exists to avoid."}, "excluded": {"languageMode": "configuration and unit assembly, not the language", "anchorPath": "the path establishes the variant and then does not enter the record", "normalizerSpecificationDigest": "the clone normalisation level specification is already a separate framed component; it is not the interpreter of the span", "grammarSelection": "which grammars this analysis selected is committed in the universe identity; it is not a property of one body"}, "bodyLanguages": ["typescript", "javascript", "rust"], "bodyLanguageByVariant": {"rs": "rust", "ts": "typescript", "tsx": "typescript", "ts-declaration": "typescript", "mts": "typescript", "cts": "typescript", "js": "javascript", "jsx": "javascript", "mjs": "javascript", "cjs": "javascript"}, "bodyLanguageLaw": "The body language is the language of the BODY, from the same suffix selector, and is closed to the body-language-version languageId enum. The bundled grammar set and that enum are held eq

